<script setup lang="ts">
import { Mail, MapPin, Phone } from '@lucide/vue'
definePageMeta({ middleware: 'auth' })
const route = useRoute(); const { find } = useStudents(); const { data: student } = await useAsyncData(`student-${route.params.id}`, () => find(Number(route.params.id)))
useSeoMeta({ title: () => student.value ? `${student.value.first_name} ${student.value.last_name} · StudentIS` : 'Student · StudentIS' })
</script>
<template><div v-if="student" class="page-shell"><PageHeader :title="`${student.first_name} ${student.last_name}`" :description="student.student_number"><template #actions><StatusBadge :status="student.status" /><BaseButton :to="`/students/${student.id}/edit`">Edit student</BaseButton></template></PageHeader><nav class="flex gap-1 overflow-x-auto border-b border-slate-200" aria-label="Student sections"><NuxtLink :to="`/students/${student.id}`" class="border-b-2 border-brand-600 px-4 py-3 text-sm font-semibold text-brand-700">Overview</NuxtLink><NuxtLink to="/enrollments" class="px-4 py-3 text-sm text-slate-500">Enrollments</NuxtLink><NuxtLink to="/grades" class="px-4 py-3 text-sm text-slate-500">Grades</NuxtLink><NuxtLink :to="`/students/${student.id}/academic-record`" class="px-4 py-3 text-sm text-slate-500">Academic record</NuxtLink></nav><div class="grid gap-6 lg:grid-cols-2"><BaseCard><h2 class="mb-5 font-semibold text-slate-900">Academic information</h2><dl class="grid grid-cols-2 gap-5 text-sm"><div><dt class="text-slate-500">Program</dt><dd class="mt-1 font-semibold">{{ student.program?.name }}</dd></div><div><dt class="text-slate-500">Year level</dt><dd class="mt-1 font-semibold">Year {{ student.year_level }}</dd></div><div><dt class="text-slate-500">Student number</dt><dd class="mt-1 font-semibold">{{ student.student_number }}</dd></div><div><dt class="text-slate-500">Status</dt><dd class="mt-1"><StatusBadge :status="student.status" /></dd></div></dl></BaseCard><BaseCard><h2 class="mb-5 font-semibold text-slate-900">Contact information</h2><div class="space-y-4 text-sm"><p class="flex items-center gap-3"><Mail class="size-4 text-slate-400" />{{ student.email ?? 'No email provided' }}</p><p class="flex items-center gap-3"><Phone class="size-4 text-slate-400" />{{ student.contact_number ?? 'No contact number provided' }}</p><p class="flex items-center gap-3"><MapPin class="size-4 text-slate-400" />{{ student.address ?? 'No address provided' }}</p></div></BaseCard></div></div></template>
